-- Boutique HOP! chez Rami Lévy (patron, 10/11/2026) : le livreur HOP! fait les courses chez Rami Lévy (comme Carrefour, BOOOM, Panzer).
-- Créée « suspendu » (invisible) tant que les produits du catalogue promo ne sont pas entrés ; ensuite status = 'actif'.
-- Logo et couverture : img/market/ramilevy-{logo,cover}.webp (petite image dans shops.logo / cover, reliée par son empreinte au fichier).
insert into public.shops (code, status, name, kind, city, address, lat, lon, contact_name, phone, whatsapp, lang, plan_until, client_pays, cash_ok, kosher,
  featured, showcase, rank, tagline, tagline_he, about, about_he, admin_note, logo, cover, hours, hours_store)
select 'HOPRAMILEVY', 'suspendu', 'HOP! chez Rami Lévy · HOP! ברמי לוי', 'epicerie', 'netanya', 'Boutique HOP!', 32.3292, 34.8566,
  'HOP!', '0527790361', '972527790361', 'fr', '2099-12-31', true, true, false, true, true, 4,
  '🛒 On fait vos courses pour vous chez Rami Lévy', '🛒 עושים לכם את הקניות ברמי לוי',
  'Les promos de Rami Lévy, au prix Rami Lévy. Vous choisissez, on fait les courses pour vous et on vous livre au plus vite.',
  'המבצעים של רמי לוי, במחיר של רמי לוי. אתם בוחרים, אנחנו עושים לכם את הקניות ומביאים הכי מהר.',
  'Boutique HOP! (service du patron). Le livreur achète chez Rami Lévy (succursale de Netanya à préciser). Produits : catalogue promo du site (pink_november2026), prix promo avec la date de fin.',
  'data:image/webp;base64,', 'data:image/webp;base64,', '[{"d":0,"h":"09:30-20:00"},{"d":1,"h":"09:30-20:00"},{"d":2,"h":"09:30-20:00"},{"d":3,"h":"09:30-20:00"},{"d":4,"h":"09:30-20:00"},{"d":5,"h":"09:30-14:00"},{"d":6,"h":""}]'::jsonb, '[{"d":0,"h":"09:30-20:00"},{"d":1,"h":"09:30-20:00"},{"d":2,"h":"09:30-20:00"},{"d":3,"h":"09:30-20:00"},{"d":4,"h":"09:30-20:00"},{"d":5,"h":"09:30-14:00"},{"d":6,"h":""}]'::jsonb
where not exists (select 1 from public.shops where code = 'HOPRAMILEVY');
insert into public.shop_photo_files (h, path) values (md5('data:image/webp;base64,'), 'img/market/ramilevy-logo.webp'), (md5('data:image/webp;base64,'), 'img/market/ramilevy-cover.webp') on conflict (h) do nothing;
insert into public.shop_categories (id, shop_id, name, position)
select md5('HOPRAMILEVY:cat:promo')::uuid, id, '🏷️ Promos Rami Lévy · מבצעי רמי לוי', 0 from public.shops where code = 'HOPRAMILEVY'
on conflict (id) do nothing;
-- Boutiques HOP! (le livreur fait l'achat)
create or replace function public.hop_shop(p_shop uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from shops where id = p_shop and code in ('HOPCARREFOUR', 'HOPBOOOM', 'HOPPANZER', 'HOPRAMILEVY'));
$$;
